EN_GB = {k: k for k in DE}

LOCALES = {
    'de': DE,
    'de_DE': DE,
    'en_GB': EN_GB,
    'nl': NL,
}


def write_locale(code, additions):
    json_path = f'/app/l10n/{code}.json'
    with open(json_path) as fh:
        data = json.load(fh)
    translations = data['translations']
    added = 0
    for k, v in additions.items():
        if k not in translations:
            translations[k] = v
            added += 1
    data['translations'] = dict(sorted(translations.items()))
    with open(json_path, 'w') as fh:
        json.dump(data, fh, ensure_ascii=False, indent=4)
        fh.write('\n')

    js_path = f'/app/l10n/{code}.js'
    plural = data.get('pluralForm', 'nplurals=2; plural=(n != 1);')
    body = json.dumps(data['translations'], ensure_ascii=False, indent=8)
    with open(js_path, 'w') as fh:
        fh.write('OC.L10N.register(\n    "souvera_shield",\n    ' + body + ',\n"' + plural + '");\n')
    print(f'{code}: +{added} strings, total {len(translations)}')


for code, additions in LOCALES.items():
    write_locale(code, additions)
